"""Explain KCSAN masks and scoped record lifetimes in beginner Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1657': ('여덟 칸짜리 점검표에서 오른쪽 네 칸만 살펴보도록 창을 뚫은 종이를 덮는다고 생각해 보세요. 가린 칸을 지우거나 잠그는 것이 아니라 검사할 칸을 고르는 것이에요.', '접근 마스크가 고르는 비트와 상태 복구를 이해합니다.', '0x0f를 00001111로 쓰세요. 0x21→0x31과 0x21→0x22에서 오른쪽 네 칸이 바뀌는지 각각 비교하세요.', ['비트는 0 또는 1을 담는 칸이고 mask는 어느 칸에 관심을 둘지 고르는 표시예요. KCSAN의 kcsan_set_access_mask는 현재 실행 문맥의 검사 설정을 바꿔요. 대상 데이터의 값을 바꾸는 함수가 아니에요.', '0이 아닌 mask를 설정하면 켜진 비트 위치의 값 변화에 보고 범위를 제한해요. 예를 들어 0x0f는 16진수 표기이고 숫자로는 15예요. 여덟 자리로 펼치면 00001111이어서 오른쪽 하위 네 비트를 선택해요.', '0x21은 00100001이고 0x31은 00110001이에요. 바뀐 칸은 선택한 하위 네 칸 밖에 있어요. 반면 0x21에서 0x22, 즉 00100010으로 바뀌면 하위 칸이 바뀌므로 이 마스크가 관심을 두는 변화예요.', '이 계산은 어떤 비트 변화를 선택하는지 보여 주는 예시예요. 선택된 변화라고 모든 실행에서 반드시 보고서가 나온다는 보장은 아니에요. 실제 보고에는 검사 도구가 접근을 관찰하는 과정과 다른 조건도 있어요.', '검사를 마친 뒤 mask를 0으로 돌리면 이 선택 비트 제한을 해제해요. 런타임은 현재 문맥의 access_mask 칸에 설정값을 저장해요. 대상 flags가 0x22였더라도 마스크 해제만으로 flags가 0이 되지는 않아요.', '마스크는 다른 비트에 잠금을 걸지 않아요. 여러 실행 흐름이 같은 숫자의 서로 다른 비트를 일반 읽기·수정·쓰기로 바꾸면 서로의 변경을 덮을 수도 있어요. 실제 갱신 보호와 검사할 범위 선택은 구별해야 해요.'], [('mask 0x0f가 선택하는 값 변화는 어디인가요?', ['상위 비트만 선택해요', '하위 네 비트의 변화를 선택해요'], '정답은 두 번째예요. 0x0f를 이진수로 쓰면 00001111이므로 오른쪽 네 칸이 켜져 있어요. 마스크는 그 위치를 선택하는 표시이지 다른 칸을 보호하는 잠금은 아니에요.'), ('검사 뒤 mask를 0으로 복구하는 이유는 무엇인가요?', ['현재 문맥의 선택 비트 제한을 해제하려는 것이에요', '대상 데이터 flags 자체에 0을 쓰려는 것이에요'], '정답은 첫 번째예요. 바꾸는 대상은 검사 설정 access_mask예요. 검사 설정을 0으로 돌리는 것과 검사하던 데이터 값을 0으로 바꾸는 것은 다른 일이에요.')]), 'os1658': ('검사 신청 카드에 대상 주소와 크기를 적어 둘 수 있어요. 카드의 한 칸을 두 용도 중 하나로 쓰면 두 정보를 동시에 따로 보관할 수는 없어요.', 'scoped 접근 구조체의 union과 각 필드의 역할을 이해합니다.', '큰 카드 안에 공용 칸(list 또는 stack_depth), ptr, size, type, ip를 그리세요. ptr는 검사 대상이고 ip는 설정한 코드 위치라고 표시하세요.', ['kcsan_scoped_access는 일정 코드 구간에서 검사할 접근 정보를 모은 구조체예요. 구조체는 관련 있는 값을 한 덩어리로 묶는 C의 자료 형식이에요. 각각의 칸을 필드 또는 멤버라고 불러요.', '앞부분은 union이고 안에 list와 stack_depth가 있어요. union은 멤버들이 같은 저장 공간을 겹쳐 쓰는 형식이에요. 구조체의 독립된 두 칸처럼 두 값을 동시에 각각 보관하는 방식이 아니에요.', 'list는 검사 목록에서 다른 항목과 연결하는 정보예요. stack_depth는 목록 항목으로 쓰이지 않는 접근 정보에 대해 초기화한 때의 호출 스택 깊이를 담는 용도라고 주석이 설명해요. 호출 스택 깊이는 함수가 다른 함수를 몇 단계 거쳐 부른 상태인지와 관련돼요.', 'ptr는 검사할 대상의 주소, size는 검사 범위의 크기, type은 읽기·쓰기 같은 접근 종류예요. 예를 들어 주소 P부터 4바이트를 읽는 접근이라고 적어 둘 수 있어요. 이 숫자 4는 함수 호출 횟수가 아니라 범위의 길이예요.', 'ip는 scoped 접근을 설정한 코드 위치를 기록해요. 데이터 주소 ptr와 용도가 달라요. 문제를 발견했을 때 어느 코드에서 검사를 시작했는지 연결하는 정보이며 인터넷 IP 주소를 뜻하는 칸이 아니에요.', '이 구조체가 있다고 대상 데이터가 자동으로 보호되지는 않아요. 정보를 초기화하고 등록하고 제거하는 과정은 런타임 함수가 담당해요. 구조체의 모양과 그 구조체를 사용하는 알고리즘을 나누어 읽으세요.'], [('union 안의 list와 stack_depth는 서로 독립된 저장 칸 두 개인가요?', ['네. 두 값을 항상 따로 보관하는 struct 멤버와 같아요', '아니요. 같은 저장 공간을 서로 다른 용도로 써요'], '정답은 두 번째예요. 원문은 두 멤버를 union 안에 둬요. 하나의 공용 칸을 역할에 따라 해석하는 구조이므로 독립된 두 값을 동시에 유지한다고 읽으면 안 돼요.'), ('이 구조체의 ip는 무엇을 기록하나요?', ['scoped 접근을 설정한 코드 위치예요', '복사할 사용자 데이터의 바이트 수예요'], '정답은 첫 번째예요. 원문의 주석은 접근을 설정한 위치라고 설명해요. 범위의 크기는 size가 담당하고 검사할 데이터의 주소는 ptr가 담당해요.')]), 'os1659': ('점검할 항목을 명단에 올리고 일이 끝나면 명단에서 빼는 모습을 생각해 보세요. 명단에 있다는 것이 별도 감시자가 매 순간 사진을 찍는다는 뜻은 아니에요.', 'scoped 검사의 등록·재검사·종료 조건을 이해합니다.', 'sa 준비 → begin으로 초기화·등록 → 런타임 검사 기회 → 같은 sa로 end를 그리세요. sa와 검사 대상의 수명도 표시하세요.', ['scoped는 정해진 코드 구간에 걸쳐 적용한다는 뜻이에요. kcsan_begin_scoped_access는 한 순간만 검사 요청을 하는 대신 종료할 때까지 검사할 범위를 등록하는 인터페이스예요.', '호출자는 sa라는 구조체 자리를 제공해요. begin은 주소 ptr, 크기 size, 접근 종류 type, 설정 위치 ip를 이 구조체에 넣고 현재 실행 문맥의 내부 목록에 연결해요. 함수는 그 sa의 주소를 돌려줘요.', '헤더 주석은 등록된 접근을 KCSAN 런타임에 진입할 때 검사한다고 설명해요. 런타임은 프로그램이 실행되는 동안 실제 검사 기능을 수행하는 코드예요. 여기서 지속적인 검사라는 표현은 이 등록 기간을 뜻하며 매 나노초 별도 스레드가 읽는다는 뜻은 아니에요.', '검사 구간이 끝나면 kcsan_end_scoped_access에 같은 sa를 전달해요. end는 앞서 한 번 begin으로 초기화한 sa를 요구해요. 초기화하지 않은 임의의 주소를 넘기거나 등록·종료의 짝을 무시하면 안 돼요.', '실제 end 구현은 목록에서 항목을 제거하고 저장된 접근 정보로 검사하는 단계도 수행해요. 끝낼 때 sa 정보가 여전히 필요하다는 뜻이에요. 등록 정보의 저장 공간과 검사 대상 메모리는 사용하는 동안 유효해야 해요.', '등록한다고 공유 데이터에 잠금이 걸리거나 객체 수명이 자동으로 연장되지는 않아요. 명단 관리의 올바름, 대상의 수명, 다른 실행 흐름과의 동기화는 각각 확인해야 해요. 등록·종료 기록만 확인한 모델은 실제 모든 경쟁 상태를 검출한 증거가 아니에요.'], [('scoped 접근은 어떤 때 검사된다고 헤더가 설명하나요?', ['별도의 실시간 감시 스레드가 언제나 매 순간 읽어요', 'KCSAN 런타임에 진입할 때 등록된 접근을 검사해요'], '정답은 두 번째예요. 주석은 내부 목록에 등록하고 런타임 호출 때 검사하는 방식을 설명해요. 지속적이라는 말만 보고 독립 감시 스레드가 항상 실행된다고 추측하면 안 돼요.'), ('end에 넘길 sa는 어떤 것이어야 하나요?', ['앞서 한 번 begin으로 초기화한 sa여야 해요', '아무 미초기화 포인터여도 돼요'], '정답은 첫 번째예요. end는 등록 정보를 읽고 목록 연결을 정리하므로 대응하는 begin이 필요해요. 아무 주소나 넘기면 유효한 등록 정보라는 조건을 충족하지 못해요.')]), 'os1660': ('방에 들어올 때 점검 카드를 등록하고 방을 나갈 때 자동으로 반납하도록 약속할 수 있어요. 코드의 지역 변수에도 구간을 벗어날 때 정리 함수를 부르는 장치를 붙일 수 있어요.', 'cleanup 종료와 고유한 지역 변수 이름의 목적을 이해합니다.', '중괄호 안에 sa 선언 → begin 초기화 → 구간의 작업 → 구간 종료 때 end 호출을 그리세요. 검사 종료와 데이터 해제는 다른 일이라고 표시하세요.', ['scope는 변수 이름을 사용할 수 있는 코드 범위예요. 보통 중괄호로 만든 블록을 생각하면 돼요. __ASSERT_EXCLUSIVE_SCOPED는 이런 범위에서 검사할 정보를 담는 지역 sa 구조체를 선언해요.', '그 변수에는 __cleanup__(kcsan_end_scoped_access)라는 컴파일러 속성이 붙어요. 속성은 컴파일러에게 특별한 처리 규칙을 알려 주는 표시예요. 정상적인 블록 종료나 해당 범위를 빠져나가는 return에서 정리 함수 호출을 연결하는 데 쓰여요.', 'cleanup은 소스 파일을 include하는 순간 실행되지 않아요. include는 코드를 준비하는 단계이고, 지역 변수의 정리는 프로그램이 실행되면서 그 변수의 범위를 벗어날 때 일어나요. 프로그램의 강제 종료까지 모든 경우에 정리를 보장한다는 뜻은 아니에요.', '매크로는 별도 _dummy_p 포인터도 선언해요. 그 초기값을 kcsan_begin_scoped_access의 반환값으로 만들므로 초기화 과정에서 begin이 실행돼요. 나중에 포인터를 사용하지 않아도 검사 등록이라는 일이 있는 호출이에요.', '같은 블록에서 이 매크로를 여러 번 쓰면 지역 변수 이름이 겹칠 수 있어요. __COUNTER__에서 얻은 번호를 이름에 붙여 서로 다른 이름을 만드는 이유예요. 전처리 단계의 이름 생성이지 공유 데이터 값을 1씩 늘리는 연산이 아니에요.', 'cleanup이 하는 일은 kcsan_end_scoped_access로 해당 검사 등록을 끝내는 것이에요. 검사하던 공유 객체를 자동으로 free하거나 잠금을 자동 해제하는 기능은 아니에요. 어떤 자원을 정리하는 함수인지 끝의 함수 이름까지 확인하세요.'], [('cleanup 속성으로 연결한 종료 함수는 언제 호출되나요?', ['C 파일을 include할 때 한 번 호출돼요', '실행 중 지역 변수의 스코프를 벗어날 때 호출돼요'], '정답은 두 번째예요. 지역 변수의 범위 종료에 정리 동작을 연결한 것이에요. 전처리에서 파일을 포함하는 단계와 실행 중 begin·end의 시점은 달라요.'), ('__COUNTER__를 지역 이름에 사용하는 이유는 무엇인가요?', ['같은 스코프에서 여러 선언의 이름 충돌을 피하려고 해요', '검사 대상 데이터에 1씩 더하려고 해요'], '정답은 첫 번째예요. 고유한 번호를 이름에 붙이면 여러 검사 카드가 서로 다른 지역 변수 이름을 가질 수 있어요. 전처리 이름 만들기는 공유 데이터 값의 갱신과 무관해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_410.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
